"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type CrossfadePrimitiveProps = ComponentProps<typeof motion.div>;

export function CrossfadePrimitive({ children, ...props }: CrossfadePrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0}}
      animate={{opacity: 1}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.2, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
